public class BaseDashState : SkillState
{
	public bool showEffects = true;

	public bool playSFX = true;

	public bool cooldownReady;

	public bool prevCDWasReady;

	public bool finishedDashing;

	public float dashDuration = 0.125f;

	public NumVarStatMod dashDurationMod;

	public BoolVarStat forceEvadeStat;

	public NumVarStatMod evadeMod;

	public BoolVarStatMod airborneMod;

	public BaseDashState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isDash = true;
		isMovementSkill = true;
		forceEvadeStat = new BoolVarStat(newBaseVal: false);
		evadeMod = new NumVarStatMod("DashEvade", 1f, 10, VarStatModType.Override);
		airborneMod = new BoolVarStatMod(SkillState.staticID, newModValue: true);
		dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
	}

	public override bool IsReady()
	{
		return parent.MovementEnabled && (!allowSelfTransition || allowRepeating || !repeatLock) && (!isUltimate || IsOverdriveReady());
	}

	public override void OnEnter()
	{
		if (parent.dashSlideIgnored)
		{
			cooldownReady = prevCDWasReady;
			disableStartCooldown = true;
		}
		else
		{
			cooldownReady = cooldownRef.Ready;
			prevCDWasReady = cooldownReady;
			disableStartCooldown = !cooldownReady;
		}
		parent.dashSlideIgnored = false;
		BaseOnEnter();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.AddMod(evadeMod);
		}
		finishedDashing = false;
		dashDurationMod.modValue = dashDuration;
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.movement.dashTimer = dashDuration;
		if (parent.inputDevice == null)
		{
			inputVector = Vector2.zero;
		}
		else if (parent.inputDevice.IsMouseDash)
		{
			inputVector = GetInputVector();
		}
		else
		{
			inputVector = GetInputVector(faceInputVector: true, (parent.inputDevice.inputScheme == ChaosInputDevice.InputScheme.Gamepad && ChaosInputDevice.lockControllerAim) ? true : false);
		}
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.DashAnimStr);
		if (showEffects && !cooldownReady)
		{
			PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
			parent.dustEmitter.EmitDirBurst(15, Globals.GetRotationVector(-inputVector).z);
			parent.dashTrails.SetActive(value: true);
		}
		if (playSFX)
		{
			SoundManager.PlayWithDistAndSPR("StandardDash", parent.transform.position);
		}
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.airborneStat.AddMod(airborneMod);
		AnnounceSkillExecuteEvent();
	}

	public override void Update()
	{
		if (finishedDashing)
		{
			ExitTransition();
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			finishedDashing = parent.movement.DashToTarget();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
		DashFinished();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.RemoveMod(evadeMod);
		}
	}

	public virtual void DashFinished()
	{
		parent.dashTrails.SetActive(value: false);
		parent.TogglePreventFallCollider(status: true);
		parent.airborneStat.RemoveMod(airborneMod);
		parent.ToggleEnemyFloorCollisions();
		parent.movement.EndMovement();
	}

	public virtual void ExitTransition()
	{
		fsm.ChangeState(SlideState.staticID);
	}
}

public class BaseJumpState : SkillState
{
	protected ThrownItem parentThrow;

	public class DashState : BaseDashState
	{
		public new static string staticID = "Dash";

		public DashState(FSM fsm, Player player)
			: base(staticID, fsm, player)
		{
			isMeleeSkill = true;
			InitChargeSkillSettings(1, 0f, skillData, this);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			if (!cooldownReady)
			{
				return;
			}
			ApplyStopElement();
			if (IsEmpowered)
			{
				WindSlam windSlam = ChaosInst<WindSlam>(WindSlam.Prefab, (Vector2)parent.attackOriginTrans.position + inputVector * 1.5f, Globals.GetRotationQuaternion(inputVector));
				windSlam.attack.SetAttackInfo(parent.skillCategory, skillID, 2);
				windSlam.attack.knockbackOverwriteVector = inputVector;
				if (inputVector.x < 0f)
				{
					windSlam.transform.localScale = new Vector3(-1f, 1f, 1f);
				}
			}
			else
			{
				AirChannel airChannel = ChaosInst<AirChannel>(AirChannel.Prefab, (Vector2)parent.attackOriginTrans.position - inputVector * 0.5f, Globals.GetRotationQuaternion(inputVector));
				airChannel.attack.SetAttackInfo(parent.skillCategory, skillID);
				airChannel.attack.knockbackOverwriteVector = inputVector;
				airChannel.targetVector = inputVector;
				airChannel.useShockwaveEffect = true;
			}
		}
	}

