	public void RemoveAllPrevents(bool xAxis = true, bool yAxis = true)
	{
		if (yAxis)
		{
			preventUpMovement = false;
			preventDownMovement = false;
		}
		if (xAxis)
		{
			preventLeftMovement = false;
			preventRightMovement = false;
		}
	}

	private void PreventMovementInDirection()
	{
		if (preventUpMovement)
		{
			dashVector = (target.Value - (Vector2)transform.position).normalized;
		}
		if (snapTo)
		{
			if (Vector2.Distance(target.Value, transform.position) < snapDistance)
			{
				transform.position = target.Value;
				dashInitiated = false;
				if (endMovementOnFinish)
				{
					EndMovement();
				}
				return true;
			}
			PreventMovementInDirection();
			rigidbody2D.velocity = dashVector * dashSpeedStat.CurrentValue;
			return false;
		}
		if (!dashInitiated)
		{
			dashInitiated = true;
			dashTimer = dashDurationStat.CurrentValue;
		}
		else if (!ignoreDashTimer)
		{
			dashTimer -= Time.fixedDeltaTime;
		}
		if (dashTimer > 0f)
		{
			PreventMovementInDirection();
			rigidbody2D.velocity = dashVector * dashSpeedStat.CurrentValue;
			return false;
		}
		dashInitiated = false;
		if (endMovementOnFinish)
		{
			EndMovement();
		}
		return true;
	}

