		orbitVector.y = Mathf.Sin(0f - orbitAngle);
		if (orbitAngle < 0f || orbitAngle > (float)Math.PI * 2f)
		{
			orbitAngle = Globals.TrueMod(orbitAngle, (float)Math.PI * 2f);
		}
