	public class HurtState : State<Entity>
	{
		public float prevHitStunDuration;

		public bool playHurtAnim = true;

		public bool exitHurtState;

		public bool firstFrame;

		protected StunEffect stunEffect;

		public bool useStunRecoveryFX;

		public NumVarStatMod animSpeedMod;

		private AnimationClip hurtAnimClip;

		private string hurtAnimStr;

		private float hurtAnimDuration;

		private float animLength;

		public bool IsStunned => stunEffect != null;

		public HurtState(string stateName, FSM parentFSM, Entity parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			prevHitStunDuration = parent.hitStunDurationModifier;
			animSpeedMod = new NumVarStatMod("HurtState", 1f, 0, VarStatModType.Override);
		}

		public override void OnEnter()
		{
			if (parent.health != null)
			{
				parent.ApplyKnockback(parent.health.lastAttack);
			}
			if (playHurtAnim)
			{
				if (fsm.previousStateName == name && !parent.ignorePrevHitStunDuration)
				{
					prevHitStunDuration -= parent.anim.GetAnimTime();
					if (prevHitStunDuration > parent.hitStunDurationModifier)
					{
						parent.hitStunDurationModifier = prevHitStunDuration;
					}
				}
				prevHitStunDuration = parent.hitStunDurationModifier;
				hurtAnimStr = "Hurt" + ((!parent.multiAnimHurt) ? string.Empty : parent.facingDirection.ToString());
				if (animLength == 0f && parent.anim != null)
				{
					hurtAnimClip = parent.anim.GetAnimClip(hurtAnimStr);
					if (hurtAnimClip != null)
					{
						animLength = hurtAnimClip.length;
					}
				}
				hurtAnimDuration = animLength * parent.hitStunDurationModifier;
				if (fsm.previousStateName == name && this.stunEffect != null)
				{
					this.stunEffect.Readjust(hurtAnimDuration);
				}
				else if (parent.hitStunDurationModifier < 10f && hurtAnimDuration >= 0.625f)
				{
					this.stunEffect = PoolManager.GetPoolItem<StunEffect>();
					this.stunEffect.duration = hurtAnimDuration;
					StunEffect stunEffect = this.stunEffect;
					Transform transform = parent.transform;
					stunEffect.Play(-1, transform, Vector3.up * 2.5f);
				}
				if (parent.animSpeedHandler != null)
				{
					parent.animSpeedHandler.Modify(animSpeedMod, givenStatus: true);
				}
				parent.anim.PlayDirectional(hurtAnimStr);
			}
			parent.ignorePrevHitStunDuration = false;
			exitHurtState = false;
			firstFrame = true;
			parent.TogglePreventFallCollider(status: false);
		}

		public override void Update()
		{
			if (firstFrame)
			{
				firstFrame = false;
				return;
			}
			exitHurtState = !playHurtAnim || parent.anim.AnimPlayed(parent.hitStunDurationModifier);
			if (exitHurtState)
			{
				ExitTransition();
			}
		}

		public override void OnExit()
		{
			if (parent.fsm.nextStateName != name)
			{
				if (stunEffect != null)
				{
					stunEffect.Stop(useStunRecoveryFX && !fsm.nextStateName.Contains("Dead") && !fsm.nextStateName.Contains("Fall"));
					stunEffect = null;
				}
				if (parent.animSpeedHandler != null)
				{
					parent.animSpeedHandler.Modify(animSpeedMod, givenStatus: false);
				}
			}
			parent.TogglePreventFallCollider(status: true);
		}

		public virtual void ExitTransition()
		{
			fsm.ChangeState(fsm.defaultStateName);
		}
	}

