	public static readonly string enemyBaseCategory = "Enemy";

	public static Dictionary<string, StatData> globalSkillData = new Dictionary<string, StatData>();

	public static Dictionary<string, Dictionary<string, Dictionary<string, StatData>>> data = new Dictionary<string, Dictionary<string, Dictionary<string, StatData>>>();

	private static List<StatData> modifiedStatDataList;

