	public static void LoadPlayerSkills(string categoryModifier = "")
	{
		LoadData(playerSkillAssetPath, statFieldStr, playerBaseCategory, categoryModifier);
	}

	public static void LoadEnemySkills(string categoryModifier = "")
	{
		LoadData(enemySkillAssetPath, statFieldStr, enemyBaseCategory, categoryModifier);
	}

	public static void LoadData(string assetPath, string statID, string category, string categoryModifier = "")
	{
		string text = category + categoryModifier;
		if (!data.ContainsKey(statID))
		{
			data[statID] = new Dictionary<string, Dictionary<string, StatData>>();
		}
		data[statID][text] = new Dictionary<string, StatData>();
		Dictionary<string, StatData> dictionary = data[statID][text];
		SkillStatContainer skillStatContainer = JsonUtility.FromJson<SkillStatContainer>(ChaosBundle.Get<TextAsset>(assetPath).text);
		int num = skillStatContainer.skillStats.Length;
		bool flag = category == "Enemy";
		for (int i = 0; i < num; i++)
		{
			skillStatContainer.skillStats[i].Initialize();
			StatData statData = new StatData(skillStatContainer.skillStats[i], text);
			List<string> value = statData.GetValue<List<string>>("targetNames");
			if (value.Contains(Globals.allyHBStr) || value.Contains(Globals.enemyHBStr))
			{
				value.Add(Globals.ffaHBStr);
			}
			if (value.Contains(Globals.allyFCStr) || value.Contains(Globals.enemyFCStr))
			{
				value.Add(Globals.ffaFCStr);
			}
			if (flag)
			{
				switch (categoryModifier)
				{
				case "Only":
					if (value.Contains(Globals.allyHBStr))
					{
						value.Remove(Globals.allyHBStr);
						value.Add(Globals.enemyHBStr);
					}
					if (value.Contains(Globals.allyFCStr))
					{
						value.Remove(Globals.allyFCStr);
						value.Add(Globals.enemyFCStr);
					}
					break;
				case "FFA":
					if (value.Contains(Globals.allyHBStr))
					{
						value.Add(Globals.enemyHBStr);
					}
					if (value.Contains(Globals.allyFCStr))
					{
						value.Add(Globals.enemyFCStr);
					}
					break;
				case "AsAlly":
					value.Remove(Globals.ffaHBStr);
					value.Remove(Globals.ffaFCStr);
					break;
				}
				statData.currentLevel = 1;
			}
			dictionary[statData.GetValue<string>("ID")] = statData;
			globalSkillData[statData.GetValue<string>("ID")] = statData;
		}
