public class SlideState : State<Player>
{
	private ChaosQuickStopwatch slideStopwatch = new ChaosQuickStopwatch(0.25f);

	public float slideSpeed = 5f;

	private bool finishedSliding;

	private bool ignoreSlide;

	private int currentIgnoreCount;

	private int maxIgnoreCount = 2;

	private SkillState dashSkill;

	private NumVarStatMod slideMoveSpeedMod;

	private float dustAngle;

	private BoolVarStatMod airborneMod;

	public static readonly string staticID = "PlayerSlide";

	public SlideState(FSM fsm, Player ent)
		: base(staticID, fsm, ent)
	{
		slideMoveSpeedMod = new NumVarStatMod(staticID, 0f, 10, VarStatModType.OverrideWithMods);
		airborneMod = new BoolVarStatMod(staticID, newModValue: true);
	}

	public override void OnEnter()
	{
		parent.anim.PlayDirectional(parent.SlideAnimStr);
		parent.movement.moveVector = parent.movement.dashVector;
		parent.dashSlideIgnored = false;
		ignoreSlide = parent.ignoreDashSlide.CurrentValue && currentIgnoreCount < maxIgnoreCount;
		if (ignoreSlide)
		{
			parent.airborneStat.AddMod(airborneMod);
			parent.TogglePreventFallCollider(status: false);
		}
		dashSkill = parent.GetDashSkill();
		dustAngle = Globals.GetRotationVector(parent.movement.dashVector).z;
		slideStopwatch.IsRunning = true;
		finishedSliding = false;
	}

	public override void Update()
	{
		if (finishedSliding)
		{
			if (!parent.HandleSkills(allowButtonHeld: true, (dashSkill != null) ? dashSkill.skillID : string.Empty))
			{
				if (parent.MovementEnabled && parent.inputDevice.GetMoveVector() != Vector2.zero)
				{
					fsm.ChangeState("Run");
				}
				else
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
		}
		else if (ignoreSlide && dashSkill != null && parent.inputDevice.GetButton("Skill" + dashSkill.skillSlot))
		{
			parent.dashSlideIgnored = true;
			dashSkill.Transition();
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedSliding)
		{
			finishedSliding = !slideStopwatch.IsRunning;
			slideMoveSpeedMod.modValue = Mathf.Lerp(slideSpeed * 0.5f, slideSpeed, slideStopwatch.TimePercentage);
			parent.movement.moveSpeedStat.AddMod(slideMoveSpeedMod);
			parent.movement.MoveToMoveVector();
			parent.dustEmitter.EmitDirBurst(1, 0f - dustAngle, 10f, -1f, 0.75f);
		}
	}

	public override void OnExit()
	{
		if (dashSkill != null && fsm.nextState == dashSkill)
		{
			currentIgnoreCount++;
		}
		else
		{
			currentIgnoreCount = 0;
		}
		parent.airborneStat.RemoveMod(airborneMod);
		parent.TogglePreventFallCollider(status: true);
		parent.movement.moveSpeedStat.RemoveMod(slideMoveSpeedMod);
		parent.movement.EndMovement();
	}
}

